import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useTier } from '../config/TierContext';
import { Tier } from '../config/tiers';

export const SIDEBAR_WIDTH = 268;

const TIERS: Tier[] = ['Starter', 'Essentials', 'Pro'];

const navItems: { path: string; label: string; icon: React.ReactNode }[] = [
  {
    path: '/dashboard',
    label: 'Dashboard',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <path d="M3 10.5L12 3l9 7.5" strokeLinecap="round" strokeLinejoin="round" />
        <path d="M5 10v10h14V10" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
  {
    path: '/search',
    label: 'Search',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <circle cx="10.5" cy="10.5" r="6.5" />
        <path d="M16 16l5 5" strokeLinecap="round" />
      </svg>
    ),
  },
  {
    path: '/portfolios',
    label: 'Portfolios',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <rect x="3" y="7" width="18" height="13" rx="2" />
        <path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" strokeLinecap="round" />
      </svg>
    ),
  },
  {
    path: '/idv-aml',
    label: 'IDV & AML',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <path d="M14 3h5v5" strokeLinecap="round" />
        <path d="M10 14L21 3" strokeLinecap="round" />
        <path d="M5 7H4a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-1" strokeLinecap="round" />
        <path d="M8 11l2 2 4-4" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
  {
    path: '/international-checks',
    label: 'International Checks',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <circle cx="12" cy="12" r="9" />
        <path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18" strokeLinecap="round" />
      </svg>
    ),
  },
  {
    path: '/analytics',
    label: 'Analytics',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <path d="M4 19V5" strokeLinecap="round" />
        <path d="M4 12h4l3-6 4 12 3-6h4" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
  {
    path: '/advanced-investigations',
    label: 'Advanced Investigations',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <path d="M9 3H5v4M15 3h4v4M9 21H5v-4M15 21h4v-4" strokeLinecap="round" />
        <circle cx="12" cy="12" r="4" />
        <path d="M15 15l4 4" strokeLinecap="round" />
      </svg>
    ),
  },
  {
    path: '/consumer-credit',
    label: 'Consumer Credit Report',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-5z" strokeLinecap="round" strokeLinejoin="round" />
        <path d="M14 3v5h5M10 13h4M10 17h8" strokeLinecap="round" />
        <circle cx="8.5" cy="13" r="1.5" fill="currentColor" stroke="none" />
      </svg>
    ),
  },
  {
    path: '/knowledge-hub',
    label: 'Knowledge Hub',
    icon: (
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
        <path d="M4 19V5a2 2 0 0 1 2-2h4v16H6a2 2 0 0 0-2 2zm16 0V5a2 2 0 0 0-2-2h-4v16h4a2 2 0 0 1 2 2z" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
];

export default function Sidebar() {
  const location = useLocation();
  const { tier, setTier, spotterEnabled } = useTier();

  const linkStyle = (path: string): React.CSSProperties => {
    const active = location.pathname === path;
    return {
      display: 'flex',
      alignItems: 'center',
      gap: 12,
      textDecoration: 'none',
      fontSize: 13.5,
      fontWeight: active ? 600 : 400,
      color: active ? '#5B21B6' : '#4B5563',
      padding: '10px 12px',
      borderRadius: 8,
      backgroundColor: active ? '#F5F3FF' : 'transparent',
      transition: 'all 0.15s ease',
      marginBottom: 2,
    };
  };

  return (
    <aside
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        bottom: 0,
        width: SIDEBAR_WIDTH,
        backgroundColor: '#ffffff',
        borderRight: '1px solid #E5E7EB',
        display: 'flex',
        flexDirection: 'column',
        zIndex: 1000,
        boxSizing: 'border-box',
      }}
    >
      <div style={{ padding: '1rem 1.15rem 0.75rem', flexShrink: 0 }}>
        <div
          style={{
            color: '#9CA3AF',
            fontSize: 10,
            fontWeight: 600,
            letterSpacing: '1px',
            textTransform: 'uppercase',
            marginBottom: 8,
          }}
        >
          Access level (demo)
        </div>
        <div style={{ display: 'flex', backgroundColor: '#F3F4F6', borderRadius: 8, padding: 3 }}>
          {TIERS.map((t) => (
            <button
              key={t}
              type="button"
              onClick={() => setTier(t)}
              style={{
                flex: 1,
                textAlign: 'center',
                padding: '6px 2px',
                fontSize: 11,
                fontWeight: t === tier ? 600 : 500,
                color: t === tier ? '#5B21B6' : '#6B7280',
                backgroundColor: t === tier ? '#ffffff' : 'transparent',
                borderRadius: 6,
                cursor: 'pointer',
                transition: 'all 0.15s ease',
                border: t === tier ? '1px solid #E5E7EB' : '1px solid transparent',
              }}
            >
              {t}
            </button>
          ))}
        </div>
        <p style={{ fontSize: 10.5, color: '#9CA3AF', margin: '8px 0 0', lineHeight: 1.4 }}>
          Starter limits filters and drill; Essentials hides AI menu actions; Pro enables Data Bot and full interactivity.
        </p>
      </div>

      <nav style={{ padding: '0.25rem 0.7rem 0.35rem', display: 'flex', flexDirection: 'column', flex: 1, overflowY: 'auto', minHeight: 0 }}>
        {navItems.map((item) => (
          <Link key={item.path} to={item.path} style={linkStyle(item.path)}>
            <span style={{ display: 'flex', alignItems: 'center', width: 22, justifyContent: 'center', color: 'inherit' }}>
              {item.icon}
            </span>
            <span style={{ flex: 1, lineHeight: 1.35, display: 'flex', alignItems: 'center', gap: 6 }}>
              {item.label}
              {item.path === '/analytics' && !spotterEnabled && (
                <span
                  style={{
                    fontSize: 9,
                    fontWeight: 700,
                    backgroundColor: '#EDE9FE',
                    color: '#7C3AED',
                    padding: '2px 6px',
                    borderRadius: 4,
                    letterSpacing: '0.4px',
                  }}
                >
                  AI: PRO
                </span>
              )}
            </span>
          </Link>
        ))}
        <div style={{ flex: 1, minHeight: 8 }} />
      </nav>

      <div
        style={{
          padding: '0.875rem 1.15rem',
          borderTop: '1px solid #F3F4F6',
          display: 'flex',
          alignItems: 'center',
          gap: 10,
        }}
      >
        <div
          style={{
            width: 36,
            height: 36,
            backgroundColor: '#5B21B6',
            borderRadius: '50%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            flexShrink: 0,
            color: '#fff',
            fontWeight: 700,
            fontSize: 12,
          }}
        >
          RF
        </div>
        <div style={{ lineHeight: 1.35 }}>
          <div style={{ color: '#2c313c', fontWeight: 600, fontSize: 13 }}>RedFlagAlert</div>
          <div style={{ color: '#9CA3AF', fontSize: 11.5 }}>{tier} · demo user</div>
        </div>
      </div>
    </aside>
  );
}
